Colors[ 0] := '0000A0'; // Blue Colors[ 1] := '008000'; // Green Colors[ 2] := 'FF0000'; // Red Colors[ 3] := 'FF6000'; // Orange Colors[ 4] := 'FFFF00'; // Yellow Colors[ 5] := 'FFFFFF'; // White Colors[ 6] := 'AABB20'; // Golden Colors[ 7] := '800080'; // Purple Colors[ 8] := '7FFF00'; // Lime Colors[ 9] := '008080'; // Teal Colors[10] := '2828FF'; // LightBlue Colors[11] := '00FF00'; // LightGreen Colors[12] := '800000'; // Brown Colors[13] := '8000CF'; // Violett Colors[14] := 'FF0080'; // LightViolett Colors[15] := '00DCB4'; // Cyan Colors[16] := 'FF69B4'; // Pink Colors[17] := '808000'; // Olive Colors[18] := 'F0E68C'; // Khaki Colors[19] := '00BFFF'; // DeepSky
R := 0.4; H := R * 1.7; N := 10;
for i := 0 to N - 1 do begin x[i] := R * cos(2 * Pi / N * i); y[i] := R * sin(2 * Pi / N * i); end;
